// 独立后任让职尾与原两个制度分别选择；新命令不能借旧PoliticsEffects版本通过。
#define POLITICAL_TERM_HANDOVER_FIXTURE_ONLY
#include "political_term_handover_rules_test.cpp"
#include "resident/domains/politics/term_handover/political_term_handover_profile.hpp"
int main(){try{
 TermFixture f;std::vector<std::pair<StableId,StableId>> modules={{"politics","1"},{"family_life","1"},{"task_message_notices","1"},{"task_message_handoffs","2"},{"political_successions","1"},{"political_successor_rounds","1"},{political_term_handover_domain,"1"}};check(take(political_term_handover_selected_version(modules))==1,"later-term profile independently selects exact original successors dependency");check(validate_political_term_handover_layout(f.common,modules,&f.terms).ok,"explicit profile requires exact empty new tail");check(!validate_political_term_handover_layout(f.common,modules,nullptr).ok,"selected missing tail refused");auto bad=modules;bad.erase(bad.end()-2);check(!political_term_handover_selected_version(bad).ok,"missing next-term policy refuses living permission");bad=modules;bad.push_back(modules.back());check(!political_term_handover_selected_version(bad).ok,"duplicate module refused");bad=modules;bad.back().second="2";check(!political_term_handover_selected_version(bad).ok,"unknown new version refused");modules.pop_back();check(validate_political_term_handover_layout(f.common,modules,nullptr).ok,"old selected modules do not add even empty new tail");check(!validate_political_term_handover_layout(f.common,modules,&f.terms).ok,"unselected new empty state refused");
 f.install();auto offer=f.commit_term("candidate",f.offer_later());check(!validate_political_term_handover_layout(f.common,modules,nullptr).ok,"old mode rejects actual new facts/results");check(validate_political_term_handover_fact_header(f.common,f.terms,*f.common.state().facts.find(offer)).ok,"actual exact source maps one payload");auto extra=f.terms;PoliticalTermHandoverAnswer wrong;wrong.id=offer;extra.answers.insert(offer,wrong);check(!validate_political_term_handover_fact_header(f.common,extra,*f.common.state().facts.find(offer)).ok,"domain alone cannot excuse second payload");
 PoliticsEffects effects;effects.fact_ids={"political_term_handover_acceptance:2"};effects.receipt_ids={"organization:3"};check(valid_political_term_handover_effect(political_term_handover_answer_command,effects),"actual accepted reply names original Office result");effects.receipt_ids.clear();check(!valid_political_term_handover_effect(political_term_handover_answer_command,effects),"accepted reply cannot omit original Office");effects.fact_ids={"political_term_handover_decline:2"};check(valid_political_term_handover_effect(political_term_handover_answer_command,effects),"decline has no Office effect");effects.fact_ids={"political_head_handover_decline:2"};check(!valid_political_term_handover_effect(political_term_handover_answer_command,effects),"old first-head source cannot masquerade as later-term reply");
 std::cout<<checks<<" later-term profile assertions; no World claim\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
